package org.sleepwell.app;
import android.app.*;import android.content.*;import android.graphics.Rect;import android.os.*;import android.view.*;import android.view.inspector.WindowInspector;import android.widget.*;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.uiautomator.UiDevice;import org.junit.Test;import java.io.*;import java.util.concurrent.*;import static org.junit.Assert.*;
/** Native settings/countdown controls, fake clock/commands and real private persistence. No capture. */
public final class TrackingDelayFlowTest {
 final Instrumentation i=InstrumentationRegistry.getInstrumentation();final Context c=i.getTargetContext();final UiDevice d=UiDevice.getInstance(i);TrackingDelayFixture f;
 interface Task{void run()throws Exception;}interface Ready{boolean check()throws Exception;}
 void waitFor(Ready ready)throws Exception{long limit=SystemClock.elapsedRealtime()+10000;while(!ready.check()){if(SystemClock.elapsedRealtime()>limit)throw new AssertionError("delay fixture did not reach its expected state");Thread.sleep(30);}}
 View root(){for(View v:WindowInspector.getGlobalWindowViews())if(v.hasWindowFocus()&&v.isAttachedToWindow()&&v.getContext().getPackageName().equals(c.getPackageName()))return v;return null;}
 View find(View v,String label,boolean switches){if(v==null)return null;if((!switches||v instanceof Switch)&&(label.contentEquals(v.getContentDescription()==null?"":v.getContentDescription())||v instanceof TextView&&label.contentEquals(((TextView)v).getText())))return v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int n=0;n<g.getChildCount();n++){View found=find(g.getChildAt(n),label,switches);if(found!=null)return found;}}return null;}
 Rect control(String label,boolean switches){Rect[] result={null};i.runOnMainSync(()->{View v=find(root(),label,switches);while(v!=null&&!v.isClickable())v=v.getParent() instanceof View?(View)v.getParent():null;if(v==null||!v.isEnabled())return;Rect area=new Rect();if(v.getGlobalVisibleRect(area)&&area.height()==v.getHeight()&&area.width()==v.getWidth()&&v.getHeight()>=Design.dp(c,48)){int[] screen=new int[2];v.getLocationOnScreen(screen);result[0]=new Rect(screen[0],screen[1],screen[0]+v.getWidth(),screen[1]+v.getHeight());}else v.requestRectangleOnScreen(new Rect(0,0,v.getWidth(),v.getHeight()),false);});return result[0];}
 void click(String label)throws Exception{click(label,false);}void click(String label,boolean switches)throws Exception{waitFor(()->control(label,switches)!=null);View[] owner={null};CountDownLatch commit=new CountDownLatch(1);i.runOnMainSync(()->{owner[0]=root();assertNotNull(owner[0]);owner[0].getViewTreeObserver().registerFrameCommitCallback(commit::countDown);owner[0].invalidate();});assertTrue(commit.await(5,TimeUnit.SECONDS));Rect r=control(label,switches);assertNotNull(label,r);i.runOnMainSync(()->assertSame("Exact focused committed input owner",owner[0],root()));assertTrue(d.click(r.centerX(),r.centerY()));}
 void text(String label)throws Exception{waitFor(()->{boolean[] found={false};i.runOnMainSync(()->found[0]=find(root(),label,false)!=null);return found[0];});}
 File folder(){File f=new File(c.getExternalFilesDir(null),"verification");assertTrue(f.isDirectory()||f.mkdirs());return f;}
 void capture(String name,String label)throws Exception{text(label);CountDownLatch frame=new CountDownLatch(1);i.runOnMainSync(()->{View v=root();assertNotNull(v);v.getViewTreeObserver().registerFrameCommitCallback(frame::countDown);v.invalidate();});assertTrue(frame.await(5,TimeUnit.SECONDS));assertTrue(d.takeScreenshot(new File(folder(),"tracking-delay-"+name+".png")));}


 void ready()throws Exception{f.idle();waitFor(()->{boolean[] ok={false};i.runOnMainSync(()->ok[0]=root()!=null&&(!(f.resumed instanceof TrackingDelayActivity)||((TrackingDelayActivity)f.resumed).drawn==f.job().state));return ok[0];});}
 void launch(Class<?> type)throws Exception{f.launch(type);ready();}
 void recreate()throws Exception{Activity old=f.resumed;i.runOnMainSync(old::recreate);waitFor(()->f.resumed!=old&&f.resumed.hasWindowFocus());ready();}
 void run(Task task)throws Exception{try(TrackingDelayFixture fixture=new TrackingDelayFixture()){f=fixture;try{task.run();}catch(Exception|AssertionError failure){try{d.takeScreenshot(new File(folder(),"tracking-delay-failure.png"));d.dumpWindowHierarchy(new File(folder(),"tracking-delay-failure.xml"));}catch(Exception capture){failure.addSuppressed(capture);}throw failure;}}}
 @Test public void defaultOffDraftRecreationSaveAndReopenPersistWithoutStarting()throws Exception{run(()->{
  launch(TrackingDelayActivity.class);capture("default","Manual start delay");assertEquals(0,f.store().minutes());
  for(String preset:new String[]{"Off","1 min","5 min","10 min","15 min","30 min"})assertNotNull("Complete preset geometry: "+preset,control(preset,false));
  click("5 min");waitFor(()->{boolean[] value={false};i.runOnMainSync(()->value[0]=((TrackingDelayActivity)f.resumed).draft==5);return value[0];});
  recreate();capture("draft-recreated","Save start delay");assertEquals(0,f.store().minutes());
  click("Save start delay");waitFor(()->f.store().minutes()==5);ready();capture("saved","Save start delay");
  launch(TrackingDelayActivity.class);capture("reopened","Manual start delay");assertEquals(5,f.store().minutes());assertNull(f.store().read());assertEquals(0,f.starts);
 });}
 @Test public void countdownRecreationCancellationAndStartNowUseExactOwnedPlan()throws Exception{run(()->{f.arm("cancel-owned");launch(TrackingActivity.class);capture("countdown","No sensors or audio are recording");assertEquals(0,f.starts);try(Store s=new Store(c,f.database)){assertTrue(s.rows("SELECT * FROM sessions").isEmpty());}recreate();capture("countdown-recreated","Cancel delayed start");assertEquals("cancel-owned",f.store().read().token);click("Cancel delayed start");waitFor(()->f.cancels==1&&f.store().read().phase==TrackingDelay.Phase.CANCELLED);launch(TrackingDelayActivity.class);capture("cancelled","Delay cancelled; no recording created");assertEquals(0,f.starts);f.arm("start-owned");launch(TrackingActivity.class);capture("second-wait","Start recording now");click("Start recording now");waitFor(()->f.starts==1&&f.store().read().phase==TrackingDelay.Phase.STARTED);launch(TrackingDelayActivity.class);capture("started","Recording began after the wait");assertEquals(f.created,f.store().read().session);try(Store s=new Store(c,f.database)){assertEquals(1,s.rows("SELECT * FROM sessions").size());assertTrue(s.rows("SELECT * FROM epochs").isEmpty());assertTrue(s.rows("SELECT * FROM clips").isEmpty());}assertEquals(1,f.starts);});}
}
